('Machining', 'Wire EDM', 'Base Plate Removal Wire EDM', 'BuildDirection', 'Wire EDM:Base Plate Removal Wire EDM//BuildDirection'),
('Machining', 'Wire EDM', 'Cutting', 'AxiGroove', 'Wire EDM:Cutting//AxiGroove'),
('Machining', 'Wire EDM', 'Cutting', 'CurvedWall', 'Wire EDM:Cutting//CurvedWall'),
('Machining', 'Wire EDM', 'Cutting', 'Perimeter', 'Wire EDM:Cutting//Perimeter'),
('Machining', 'Wire EDM', 'Cutting', 'PlanarFace', 'Wire EDM:Cutting//PlanarFace'),
('Machining', 'Wire EDM', 'Cutting', 'SimpleHole', 'Wire EDM:Cutting//SimpleHole'),
('Machining', 'Wire EDM', 'End Machining', 'End', 'Wire EDM:End Machining//End'),
('Machining', 'Wire EDM', 'Wire EDM Cutting', 'MultiStepHole', 'Wire EDM:Wire EDM Cutting//MultiStepHole'),
('Machining', 'Wire EDM', 'Wire EDM Cutting', 'RingedHole', 'Wire EDM:Wire EDM Cutting//RingedHole'),
('Machining', 'Wire EDM', 'Wire EDM Cutting', 'Slot', 'Wire EDM:Wire EDM Cutting//Slot'),
('Machining', 'Wire EDM', 'Wire EDM', 'Flat', 'Wire EDM:Wire EDM//Flat')
) AS v(process_group, process_name, operation_category, feature_type, raw)
  ON pt.process_group = v.process_group AND pt.process_name = v.process_name
ON CONFLICT (canonical_process_id, raw_compound_string) DO NOTHING;

-- Aliases (4 rows)
INSERT INTO process_taxonomy_aliases (canonical_process_id, alias, source)
SELECT pt.id, v.alias, v.source
FROM process_taxonomy pt
JOIN (VALUES
('Sheet Metal', 'Waterjet Cutting', 'Waterjet Cut', 'process_operations_json'),
('Sheet Metal', 'Laser Puch', 'Laser Punch', 'manual'),
('Sheet Metal', 'Progressive die', 'Progressive Die', 'process_operations_json'),
('Plastic & Rubber', 'Structural foam molding', 'Structural Foam Molding', 'process_operations_json')
) AS v(process_group, process_name, alias, source)
  ON pt.process_group = v.process_group AND pt.process_name = v.process_name
ON CONFLICT DO NOTHING;

COMMIT;

